import {normalizeFeed,filtered,amapLink,toWgs84} from './food-core.js';
import {translate as t,locale} from './i18n.js';
const $=id=>document.getElementById(id);const state={rows:[],map:null,markers:[],active:null};
function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
function link(text,url){const node=element('a',text);node.href=url;node.target='_blank';node.rel='noopener noreferrer';return node;}
function matches(){return filtered(state.rows,$('search').value,$('city').value,$('category').value);}
function popup(p){const box=element('div');box.append(element('h3',p.name),element('p',p.city+' · '+t(p.category)),element('p',p.address||t('Check the original venue listing.')),link(t('Open in Amap ↗'),amapLink(p)));if(p.articleUrl)box.append(element('br'),link(t('Original recommendation ↗'),p.articleUrl));return box;}
function select(p){state.active=p.id;document.querySelectorAll('.venue-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===p.id));if(state.map){state.map.setView(toWgs84(p.lng,p.lat),15);const marker=state.markers.find(m=>m.venueId===p.id);if(marker)marker.openPopup();}else{$('map-status').textContent=t('Selected: {name}. Load the map to see its marker.',{name:p.name});}}
function markers(){if(!state.map)return;state.markers.forEach(m=>m.remove());state.markers=[];for(const p of matches()){const marker=L.circleMarker(toWgs84(p.lng,p.lat),{radius:8,color:'#fcfcf8',weight:2,fillColor:'#466f7f',fillOpacity:.95}).addTo(state.map).bindPopup(popup(p));marker.venueId=p.id;marker.on('click',()=>select(p));state.markers.push(marker);}}
function fit(){if(state.map&&state.markers.length)state.map.fitBounds(L.featureGroup(state.markers).getBounds(),{padding:[40,40],maxZoom:13});}
function render(){const rows=matches();$('result-count').textContent=t('Places to explore: {count}',{count:rows.length});$('results').replaceChildren();if(!rows.length)$('results').append(element('p',t('No matching places. Try another city or reset the filters.'),'empty-state'));for(const p of rows){const card=element('article',undefined,'venue-card');card.dataset.id=p.id;const top=element('div',undefined,'venue-top');top.append(element('span',p.city),element('span',t(p.category)));const actions=element('div',undefined,'venue-actions');const button=element('button',t('Show on map'));button.type='button';button.addEventListener('click',()=>select(p));actions.append(button,link(t('Amap ↗'),amapLink(p)));if(p.articleUrl)actions.append(link(t('Original ↗'),p.articleUrl));card.append(top,element('h2',p.name),element('p',p.address||t('Address details in the original listing.')),actions);$('results').append(card);}markers();}
async function loadMap(){
 const button=$('load-map');button.disabled=true;button.textContent=t('Loading the map…');
 try{
  if(!window.L)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/assets/vendor/leaflet.js';script.onload=resolve;script.onerror=()=>reject(new Error('Map library unavailable'));document.head.append(script);});
  $('map').replaceChildren();state.map=L.map('map',{scrollWheelZoom:false,zoomControl:false}).setView([34.3,108.9],4);
  L.control.zoom({zoomInTitle:t('Zoom in'),zoomOutTitle:t('Zoom out')}).addTo(state.map);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> '+t('contributors'),updateWhenIdle:true,keepBuffer:1}).addTo(state.map).on('tileerror',()=>{$('map-status').textContent=t('Some map tiles are unavailable; the venue list and Amap links still work.');});
  markers();fit();$('map-status').textContent=t('Approximate WGS84 markers · source coordinates remain GCJ-02');$('fit-map').hidden=false;
  if(state.active){const p=state.rows.find(p=>p.id===state.active);if(p)select(p);}
 }catch(error){$('map-status').textContent=t('The map could not load. The venue list and Amap links remain available.');if(button.isConnected){button.disabled=false;button.textContent=t('Try loading the map again');}}
}
async function load(){try{const response=await fetch('/data/food.json');if(!response.ok)throw new Error('Collection unavailable');const data=await response.json();state.rows=normalizeFeed(data);$('total-count').textContent=state.rows.length;const date=new Date(data.retrievedAt);$('updated').textContent=Number.isNaN(date.valueOf())?t('Public source · CacheTide'):t('Source changed {date}',{date:date.toLocaleDateString({zh:'zh-CN',en:'en-GB',ru:'ru-RU',ja:'ja-JP'}[locale],{day:'numeric',month:'short',year:'numeric'})});for(const [id,values] of [['city',[...new Set(state.rows.map(p=>p.city))].sort()],['category',[...new Set(state.rows.map(p=>p.category))].sort()]])for(const value of values){const option=element('option',id==='category'?t(value):value);option.value=value;$(id).append(option);}render();}catch(error){$('result-count').textContent=t('Collection temporarily unavailable');$('updated').textContent=t('No private or fabricated data was substituted.');$('results').replaceChildren(element('p',t('The public collection could not be loaded. Please return later or visit the original source.'),'empty-state'));}}
$('search').addEventListener('input',render);$('city').addEventListener('change',()=>{render();fit();});$('category').addEventListener('change',()=>{render();fit();});$('reset').addEventListener('click',()=>{$('search').value='';$('city').value='';$('category').value='';render();fit();});$('load-map').addEventListener('click',loadMap);$('fit-map').addEventListener('click',fit);load();
